# Generated by the start-bridge codemod for whiteboards; re-run it instead of editing.
"""Validate and preserve the whiteboards staging artifact; never deploy.

Reuses the reviewed Apps seal/restore implementation with this app's Worker
identity, public files and source-SHA channel.
"""
import importlib.util
import os
from pathlib import Path

PROFILE = os.environ.get("VITE_WHITEBOARDS_NATIVE_PROFILE", "staging")
if PROFILE not in ("staging", "production"):
    raise ValueError("Unknown whiteboards native profile")
WORKER = (
    "tuturuuu-whiteboards"
    if PROFILE == "production"
    else "tuturuuu-whiteboards-vite-staging"
)
PUBLIC_FILES = (
    "android-chrome-192x192.png",
    "android-chrome-512x512.png",
    "apple-touch-icon.png",
    "favicon-16x16.png",
    "favicon-32x32.png",
    "favicon.ico",
    "media/background/auth-featured-bg.jpg",
    "media/background/placeholder.jpg",
    "media/background/transparent-light.png",
    "media/background/transparent.png",
    "media/logos/dark-rounded.png",
    "media/logos/dark.png",
    "media/logos/easy.png",
    "media/logos/light-rounded.png",
    "media/logos/light.png",
    "media/logos/mira-dark.png",
    "media/logos/mira-light.png",
    "media/logos/nova/nova-transparent.png",
    "media/logos/og-image.png",
    "media/logos/transparent.png",
    "media/logos/upskii/upskii-transparent.png",
    "media/official-logos/dark-logo-mono.png",
    "media/official-logos/dark-logo-mono.svg",
    "media/official-logos/dark-logo.png",
    "media/official-logos/dark-logo.svg",
    "media/official-logos/light-logo-mono.png",
    "media/official-logos/light-logo-mono.svg",
    "media/official-logos/light-logo.png",
    "media/official-logos/light-logo.svg",
    "robots.txt",
    "site.webmanifest",
)


def load():
    path = Path(__file__).with_name("apps-native-artifact.py")
    spec = importlib.util.spec_from_file_location("whiteboards_native_artifact_base", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.IDENTITY = {
        **module.IDENTITY,
        "name": WORKER,
        "vars": {"TUTURUUU_NOINDEX": "0" if PROFILE == "production" else "1"},
        "compatibility_date": "2026-10-12",
        "compatibility_flags": ["nodejs_compat","global_fetch_strictly_public"],
        "workers_dev": False,
        "preview_urls": False,
    }
    module.NORMALIZED_DEFAULTS = {**module.NORMALIZED_DEFAULTS, "topLevelName": WORKER}
    module.RECEIPT = "whiteboards-native-artifact.json"
    module.PUBLIC_FILES = PUBLIC_FILES
    return module


def main():
    # The shared CLI reads its exact source from APPS_SOURCE_SHA.
    if "WHITEBOARDS_SOURCE_SHA" in os.environ:
        os.environ["APPS_SOURCE_SHA"] = os.environ["WHITEBOARDS_SOURCE_SHA"]
    else:
        os.environ.pop("APPS_SOURCE_SHA", None)
    load().main()


if __name__ == "__main__":
    main()
